 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Thank you for calling Nimbus Telecom. My name is Nisha. How can I help you today?",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "Hi Nisha, I'm Aisha Reddy. I'm calling because I've had enough of the constant signal drops in my area. It's completely unacceptable.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I am very sorry to hear that you've been experiencing connectivity issues, Ms. Reddy. I can certainly look into this for you.",
      "tags": [
        "empathy"
      ]
    },
    {
      "speaker": "customer",
      "text": "I don't want it looked into anymore. I just want to cancel my service.",
      "tags": [
        "churn_signal"
      ]
    },
    {
      "speaker": "agent",
      "text": "I understand. Before we proceed with any account changes, could you please provide your account number?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "My account number is 14182295.",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "Thank you. And just to confirm, is your phone number 91913 66527 and your email aisha.91@examplemail.com?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Yes, that's correct.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I see the account here. I can start the process to close the account for you.",
      "tags": [
        "action:cancellation_or_retention"
      ]
    },
    {
      "speaker": "customer",
      "text": "Fine. I also have an outstanding balance of twenty dollars that I want to pay now so there are no issues later.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I can take that payment. Please go ahead and read me your card details.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "It is four seven eight zero zero eight three seven four zero seven one eight eight one six.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Thank you. I have processed that payment.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "This is ridiculous. I've spent hours on the phone over the last month and I'm still just paying to leave. This is the worst service I've ever had.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I apologize for the frustration this has caused you.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Apologies don't fix my signal! I'm done with this company.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Is there anything else I can assist you with today? I will submit the cancellation request now. Goodbye.",
      "tags": [
        "closure"
      ]
    }
  ]
}
